function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(s)) return 's is lowercase words separated by single spaces, with no leading or trailing space.';
  return null;
}

