function countAnagrams(s) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) result = result * base % MOD;
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  };

  const fact = [1n];
  for (let k = 1; k <= s.length; k++) {
    fact.push(fact[k - 1] * BigInt(k) % MOD);
  }

  let numerator = 1n;
  let denominator = 1n;
  for (const word of s.split(' ')) {
    const count = new Array(26).fill(0);
    for (const letter of word) {
      count[letter.charCodeAt(0) - 97]++;
    }
    numerator = numerator * fact[word.length] % MOD;
    for (const repeats of count) {
      denominator = denominator * fact[repeats] % MOD;
    }
  }
  return Number(numerator * power(denominator, MOD - 2n) % MOD);
}

