function countAnagrams(s) {
  // Exact count: place each distinct letter in turn, choosing which free slots it takes.
  const choose = (n, k) => {
    let ways = 1n;
    for (let i = 1; i <= k; i++) ways = ways * BigInt(n - k + i) / BigInt(i);
    return ways;
  };
  let total = 1n;
  for (const word of s.split(' ')) {
    let remaining = word.length;
    for (const letter of new Set(word)) {
      const times = word.split(letter).length - 1;
      total *= choose(remaining, times);
      remaining -= times;
    }
  }
  return Number(total % 1000000007n);
}

