function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const alphabet = 1 + pick(large ? 26 : 4);
  const longest = large ? [3, 40, 600, 10000][pick(4)] : 1 + pick(7);
  const wordCount = large ? 10000 : 1 + pick(4);
  const limit = large ? 9000 + pick(1001) : 40;
  const words = [];
  let length = -1;
  while (words.length < wordCount) {
    let wordLength = 1 + pick(longest);
    if (length + 1 + wordLength > limit) wordLength = limit - length - 1;
    if (wordLength < 1) break;
    let word = '';
    for (let i = 0; i < wordLength; i++) word += String.fromCharCode(97 + pick(alphabet));
    words.push(word);
    length += 1 + wordLength;
  }
  return [words.join(' ')];
}
